from sqlalchemy import Column, Float, String

from app.database.connection import Base


class SosShare(Base):
    """A temporary live-location share for an emergency. Deleted when ended or expired."""
    __tablename__ = "sos_shares"

    # Random id generated by the browser; it is the read link sent to family.
    id = Column(String(64), primary_key=True)
    # Only the phone that created the share knows the key behind this hash.
    key_hash = Column(String(64), nullable=False)
    lat = Column(Float, nullable=False)
    lon = Column(Float, nullable=False)
    accuracy_m = Column(Float)
    symptom_started_at = Column(Float)
    hospital_name = Column(String(200))
    hospital_lat = Column(Float)
    hospital_lon = Column(Float)
    created_at = Column(Float, nullable=False, index=True)
    updated_at = Column(Float, nullable=False)
